          ]
        },
        {
          "proposicao": "A fonte associa o descomissionamento ao fim da vida útil da plataforma ou à exaustão do campo com consequente encerramento das atividades, conectando a decisão de desativar a condições técnicas e econômicas do ativo.",
          "trechos": [
            "E7573ab8447466b08:0:697",
            "E7573ab8447466b08:697:1389"
          ],
          "condicoes": [
            "quando a plataforma atinge sua vida útil ou o campo se esgota",
            "também menciona limite econômico"
